/** Combat coverage log (seed 1): sign a contract, jump into the seeded
 *  encounter, then take every stance — fight (lands a hit, hull 2 -> 1), run
 *  (pilot check fails), talk (check fails) — carry the unresolved encounter
 *  across end-day, and finish it on day 2 with a fight that resolves
 *  `defeated` and completes the pending travel to system 2. */
export const REPLAY_LOG_COMBAT: ProtocolRequest[] = [
  { type: 'new-game', seed: 1 },
  { type: 'start-day' },
  {
    type: 'apply-action',
    action: { type: 'Trade', action: 'sign-contract', contractIndex: 0, spendDie: 0 },
  },
  { type: 'apply-action', action: { type: 'Travel', destinationId: 2, spendDie: 1 } },
  {
    type: 'apply-action',
    action: { type: 'Combat', stance: 'fight', targetId: 'npc-the-chef', spendDie: 2 },
  },
  {
    // T-1207: run is now an OPPOSED PILOT roll. Under seed 1 the die-3 slot
    // (value 7) TIES the enemy pursuit total and would ESCAPE (ties break to the
    // player), collapsing the encounter before the day boundary; the die-4 slot
    // (value 4) loses the opposed roll, so the run fails and the encounter
    // persists into day 2 as the fixture intends. Run + talk dice swapped to keep
    // the scenario intact.
    type: 'apply-action',
    action: { type: 'Combat', stance: 'run', targetId: 'npc-the-chef', spendDie: 4 },
  },
  {
    type: 'apply-action',
    action: { type: 'Combat', stance: 'talk', targetId: 'npc-the-chef', spendDie: 3 },
  },
  { type: 'end-day' },
  { type: 'start-day' },
  {
    type: 'apply-action',
    action: { type: 'Combat', stance: 'fight', targetId: 'npc-the-chef', spendDie: 0 },
  },
  { type: 'apply-action', action: { type: 'Wait' } },
  { type: 'end-day' },
];

/** T-1604b · Hold-release coverage log (seed 7). A THIRD log rather than an
 *  extension of the two above, deliberately: `abandon-contract` needs an UNSPENT
 *  die and a FULL hold at the same moment, which neither existing log has
 *  spare — and splicing an action into either would move a golden that has been
 *  stable for six tasks, burying a real regression under a re-pin. Its own log
 *  and its own golden keep both of those honest.
 *
 *  Covers the verb's three contractual beats end to end through
 *  `handleMessage` → `applyPlayerAction` → `resolveTrade`:
 *   1. abandon with an EMPTY hold → typed refusal (`TradeEvent{success:false}`),
 *      no die spent;
 *   2. sign, then abandon → hold cleared, one die spent, `TradeEvent{success:true}`
 *      carrying the forfeited destination/cargo/payment;
 *   3. sign AGAIN on the same day → the point of the whole fix: a hold that could
 *      not be re-let is exactly half of UGT finding F2's poverty trap. */
export const REPLAY_LOG_ABANDON: ProtocolRequest[] = [
  { type: 'new-game', seed: 7 },
  { type: 'start-day' },
  // (1) Nothing in the hold — a typed refusal that burns no die.
  { type: 'apply-action', action: { type: 'Trade', action: 'abandon-contract', spendDie: 0 } },
  {
    type: 'apply-action',
    action: { type: 'Trade', action: 'sign-contract', contractIndex: 0, spendDie: 0 },
  },
  // (2) Dump the run: one die, the whole payment forfeited, hold clear.
  { type: 'apply-action', action: { type: 'Trade', action: 'abandon-contract', spendDie: 1 } },
  // (3) The hold takes work again.
  {
    type: 'apply-action',
    action: { type: 'Trade', action: 'sign-contract', contractIndex: 0, spendDie: 2 },
  },
  { type: 'end-day' },
];

